import React from 'react';
import { Link } from 'react-router-dom';
import { FaFacebookF, FaInstagram, FaYoutube, FaWhatsapp, FaArrowUp } from 'react-icons/fa';

// --- Styles for the Footer Component ---
const styles = {
  footer: {
    backgroundColor: '#b2c2b3', // Muted green background from the image
    color: '#ffffff',
    padding: '60px 20px 20px 20px',
    fontFamily: 'sans-serif',
    position: 'relative',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  grid: {
    display: 'flex',
    justifyContent: 'space-between',
    gap: '30px',
    flexWrap: 'wrap', // Allows columns to stack on smaller screens
    marginBottom: '40px',
  },
  column: {
    flex: 1,
    minWidth: '200px', // Ensures columns don't get too squished
  },
  heading: {
    fontWeight: 'bold',
    fontSize: '1.1rem',
    marginBottom: '20px',
  },
  list: {
    listStyle: 'none',
    padding: 0,
    margin: 0,
  },
  listItem: {
    marginBottom: '10px',
  },
  link: {
    color: '#ffffff',
    textDecoration: 'none',
    transition: 'opacity 0.3s ease',
  },
  contactInfo: {
    lineHeight: 1.6,
  },
  socialIcons: {
    display: 'flex',
    gap: '15px',
    marginTop: '15px',
  },
  socialIconLink: {
    color: '#b2c2b3',
    backgroundColor: '#ffffff',
    borderRadius: '50%',
    width: '40px',
    height: '40px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    textDecoration: 'none',
    transition: 'transform 0.3s ease',
  },
  footerBottom: {
    borderTop: '1px solid rgba(255, 255, 255, 0.2)',
    paddingTop: '20px',
    marginTop: '20px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    flexWrap: 'wrap',
    fontSize: '0.9rem',
  },
  copyright: {
    textAlign: 'center',
    flex: 1,
  },
  // Floating Buttons
  floatingButtons: {
    position: 'fixed',
    bottom: '20px',
    right: '20px',
    display: 'flex',
    flexDirection: 'column',
    gap: '10px',
    zIndex: 1000,
  },
  iconButton: {
    width: '50px',
    height: '50px',
    borderRadius: '50%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    color: '#ffffff',
    cursor: 'pointer',
    boxShadow: '0 4px 8px rgba(0,0,0,0.2)',
    border: 'none',
  },
  whatsappButton: {
    backgroundColor: '#25D366',
  },
  scrollTopButton: {
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
  }
};

// --- Footer Component ---
const Footer = () => {

  // Function to scroll to the top of the page
  const handleScrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    });
  };

  return (
    <>
      <footer style={styles.footer}>
        <div style={styles.container}>
          <div style={styles.grid}>
            {/* Column 1: Follow Us */}
            <div style={styles.column}>
              <h3 style={styles.heading}>Follow Us</h3>
              <div style={styles.socialIcons}>
                <a href="https://facebook.com" target="_blank" rel="noopener noreferrer" style={styles.socialIconLink}><FaFacebookF /></a>
                <a href="https://instagram.com" target="_blank" rel="noopener noreferrer" style={styles.socialIconLink}><FaInstagram /></a>
                <a href="https://youtube.com" target="_blank" rel="noopener noreferrer" style={styles.socialIconLink}><FaYoutube /></a>
              </div>
            </div>

            {/* Column 2: Main Menu */}
            <div style={styles.column}>
              <h3 style={styles.heading}>Main Menu</h3>
              <ul style={styles.list}>
                <li style={styles.listItem}><Link to="/" style={styles.link}>Home</Link></li>
                <li style={styles.listItem}><Link to="/categories" style={styles.link}>Categories</Link></li>
                <li style={styles.listItem}><Link to="/about" style={styles.link}>About us</Link></li>
                <li style={styles.listItem}><Link to="/contact" style={styles.link}>Contact us</Link></li>
              </ul>
            </div>

            {/* Column 3: Information */}
            <div style={styles.column}>
              <h3 style={styles.heading}>Information</h3>
              <ul style={styles.list}>
                <li style={styles.listItem}><Link to="/privacy-policy" style={styles.link}>Privacy Policy</Link></li>
                <li style={styles.listItem}><Link to="/shipping-policy" style={styles.link}>Shipping Policy</Link></li>
                <li style={styles.listItem}><Link to="/refund-policy" style={styles.link}>Return & Refund Policies</Link></li>
                <li style={styles.listItem}><Link to="/terms-of-service" style={styles.link}>Terms of service</Link></li>
              </ul>
            </div>

            {/* Column 4: Contact */}
            <div style={styles.column}>
              <h3 style={styles.heading}>Contact</h3>
              <div style={styles.contactInfo}>
                <p>No. 9, Vijaya Nagar, Wahab Nagar, Reddypalayam Road, Srinivasapuram Post, Thanjavur, Tamil Nadu-613009.</p>
                <p>Mobile: +91 9786424450</p>
                <p>Email: vaseegrahvedatnj@gmail.com</p>
              </div>
            </div>
          </div>

          <div style={styles.footerBottom}>
            {/* The language selector can be implemented here if needed */}
            <div /> {/* Empty div for spacing */}
            <p style={styles.copyright}>Copyright © 2025 vaseegrah veda All rights reserved</p>
            <div /> {/* Empty div for spacing */}
          </div>
        </div>
      </footer>

      {/* Floating Action Buttons */}
      <div style={styles.floatingButtons}>
        <a href="https://wa.me/919786424450" target="_blank" rel="noopener noreferrer" style={{...styles.iconButton, ...styles.whatsappButton}} aria-label="Chat on WhatsApp">
          <FaWhatsapp size={24} />
        </a>
        <button onClick={handleScrollToTop} style={{...styles.iconButton, ...styles.scrollTopButton}} aria-label="Scroll to top">
          <FaArrowUp size={20} />
        </button>
      </div>
    </>
  );
};

export default Footer;
